// ============================================================================
// COLETA: lê os RSS/Atom de todas as fontes e escolhe as notícias do dia
// ============================================================================
// Não usa bibliotecas: um leitor simples de XML que entende RSS 2.0 e Atom.
// `baixar(url)` é injetado: no n8n usa this.helpers.httpRequest; no teste local, fetch.

const ENTIDADES = { amp: "&", lt: "<", gt: ">", quot: '"', apos: "'", nbsp: " ", hellip: "…", mdash: "—", ndash: "–", rsquo: "’", lsquo: "‘", rdquo: "”", ldquo: "“" };

function decodificar(s) {
  return String(s || "")
    .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, "$1")
    .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
    .replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(Number(d)))
    .replace(/&([a-z]+);/gi, (m, n) => ENTIDADES[n.toLowerCase()] ?? m);
}

function textoLimpo(html, limite) {
  const t = decodificar(decodificar(html))
    .replace(/<(script|style)[\s\S]*?<\/\1>/gi, " ")
    .replace(/<[^>]+>/g, " ")
    .replace(/\s+/g, " ")
    .trim();
  return limite && t.length > limite ? t.slice(0, limite).replace(/\s\S*$/, "") + "…" : t;
}

function tag(bloco, nomes) {
  for (const n of nomes) {
    const m = bloco.match(new RegExp(`<${n}(?:\\s[^>]*)?>([\\s\\S]*?)</${n}>`, "i"));
    if (m && m[1].trim()) return m[1];
  }
  return "";
}

function linkDoItem(bloco) {
  const atom = [...bloco.matchAll(/<link\b([^>]*?)\/?>/gi)]
    .map(m => m[1])
    .filter(a => /href=/.test(a));
  const alt = atom.find(a => !/rel=/.test(a) || /rel=["']alternate["']/.test(a));
  if (alt) return decodificar(alt.match(/href=["']([^"']+)["']/)[1]);
  const rss = tag(bloco, ["link"]);
  if (rss) return decodificar(rss).trim();
  const guid = tag(bloco, ["guid", "id"]);
  return /^https?:/.test(decodificar(guid).trim()) ? decodificar(guid).trim() : "";
}

function lerFeed(xml, tamanhoTexto = 4000) {
  const blocos = xml.match(/<item\b[\s\S]*?<\/item>/gi) || xml.match(/<entry\b[\s\S]*?<\/entry>/gi) || [];
  return blocos.map(b => {
    const data = new Date(decodificar(tag(b, ["pubDate", "published", "dc:date", "updated"])).trim());
    return {
      titulo: textoLimpo(tag(b, ["title"])),
      link: linkDoItem(b),
      data: isNaN(data) ? null : data.toISOString(),
      // Prefere o texto completo (content:encoded) ao resumo curto (description).
      trecho: textoLimpo(tag(b, ["content:encoded", "content", "description", "summary"]), tamanhoTexto),
    };
  }).filter(i => i.titulo && /^https?:\/\//.test(i.link));
}

// Normaliza o link para não repetir a mesma notícia (tira ?utm_..., #, barra final).
function chave(link) {
  try {
    const u = new URL(link);
    [...u.searchParams.keys()].filter(k => /^utm_|^ref$|^source$/i.test(k)).forEach(k => u.searchParams.delete(k));
    u.hash = "";
    return (u.host.replace(/^www\./, "") + u.pathname.replace(/\/+$/, "") + u.search).toLowerCase();
  } catch { return link; }
}

async function coletar(baixar, { temas, config, jaEnviados = [], agora = new Date() }) {
  const enviados = new Set(jaEnviados);
  const vistos = new Set();
  const falhas = [];

  // Baixa tudo em paralelo; uma fonte fora do ar não derruba a newsletter.
  const porFonte = await Promise.all(temas.flatMap(tema => tema.fontes.map(async fonte => {
    try {
      const xml = await baixar(fonte.url);
      return lerFeed(String(xml), config.TAMANHO_TEXTO).map(i => ({ ...i, tema: tema.id, fonte: fonte.nome, idioma: fonte.idioma }));
    } catch (e) {
      falhas.push(`${fonte.nome}: ${e.message || e}`);
      return [];
    }
  })));

  const todos = porFonte.flat().filter(i => {
    const k = chave(i.link);
    if (enviados.has(k) || vistos.has(k)) return false;
    vistos.add(k);
    return true;
  });

  const idade = i => i.data ? (agora - new Date(i.data)) / 36e5 : Infinity;
  const escolhidos = [];

  for (const tema of temas) {
    const doTema = todos.filter(i => i.tema === tema.id && idade(i) >= -2);
    // Como entra só um artigo por área, prefere os que trazem texto suficiente
    // para uma tradução de verdade (e não só uma frase de chamada). Ordem:
    // completos recentes → completos de até 4 dias → recentes → até 4 dias.
    const recentes = doTema.filter(i => idade(i) <= config.JANELA_HORAS);
    const ate4dias = doTema.filter(i => idade(i) <= config.JANELA_MAXIMA_HORAS);
    const completo = i => i.trecho.length >= 800;
    const janela = [recentes.filter(completo), ate4dias.filter(completo), recentes, ate4dias]
      .find(lista => lista.length >= config.ITENS_POR_TEMA) || ate4dias;

    // Revezamento entre fontes (mais recente de cada uma primeiro) para não
    // encher a editoria com um único veículo.
    const filas = new Map();
    for (const i of janela.sort((a, b) => new Date(b.data) - new Date(a.data))) {
      if (!filas.has(i.fonte)) filas.set(i.fonte, []);
      filas.get(i.fonte).push(i);
    }
    const ordem = [...filas.values()].sort((a, b) => new Date(b[0].data) - new Date(a[0].data));
    const pegos = [];
    while (pegos.length < config.ITENS_POR_TEMA && ordem.some(f => f.length)) {
      for (const fila of ordem) if (fila.length && pegos.length < config.ITENS_POR_TEMA) pegos.push(fila.shift());
    }
    escolhidos.push(...pegos);
  }

  escolhidos.forEach((item, n) => { item.id = `n${n + 1}`; item.chave = chave(item.link); });
  return { itens: escolhidos, falhas, totalLidos: todos.length };
}

// ============================================================================
// TRADUÇÃO E LINGUAGEM ACESSÍVEL (Claude API)
// ============================================================================
// Monta UM pedido para a API da Anthropic com os artigos do dia (um por área).
// O Claude traduz para o português (quando o original está em outra língua) e
// devolve, em linguagem simples, título, texto em parágrafos e "por que importa". A resposta vem em JSON validado
// (structured outputs), então o n8n não precisa adivinhar o formato.

const INSTRUCOES = `Você escreve a newsletter diária da Osmo, uma plataforma brasileira de trabalho freelance pensada para pessoas neurodivergentes (TDAH, autismo, dislexia e outras). Quem lê são freelancers e contratantes de várias áreas.

Você recebe um artigo por área. Muitos estão em outras línguas (inglês, espanhol etc.). Para cada artigo, escreva em português do Brasil:
- "titulo": o título traduzido para o português, claro e direto, com até 90 caracteres. Traduza o sentido, não palavra por palavra.
- "paragrafos": a versão em português do artigo, em 3 a 4 parágrafos curtos (de 2 a 4 frases cada, cerca de 200 palavras no total). Traduza fielmente as informações principais do texto recebido, na ordem em que aparecem, e deixe de fora detalhes secundários. Se o texto recebido for curto, escreva menos parágrafos; não complete com suposições.
- "por_que_importa": 1 frase dizendo o que muda na prática para quem trabalha como freelancer ou contrata freelancers nessa área.

Regras de linguagem acessível:
- Frases curtas, uma ideia por frase. Ordem direta: quem fez o quê.
- Sem ironia, metáforas ou expressões de duplo sentido.
- Explique termos técnicos ou siglas na primeira vez em poucas palavras, entre parênteses.
- Nomes de produtos e empresas ficam como no original.
- Não use caixa alta para dar ênfase, nem emojis.
- Use somente as informações do título e do texto recebidos. Não invente números, datas, citações ou detalhes. Se o texto recebido for curto, escreva um texto curto.
- Não exagere a importância da notícia nem crie urgência.

Escreva também "abertura": 1 ou 2 frases de boas-vindas, calmas e objetivas, citando de forma geral os assuntos dos artigos. Sem saudação de horário ("bom dia") e sem pontos de exclamação.

Devolva um item para cada "id" recebido, com o mesmo "id".`;

const ESQUEMA = {
  type: "object",
  properties: {
    abertura: { type: "string" },
    itens: {
      type: "array",
      items: {
        type: "object",
        properties: {
          id: { type: "string" },
          titulo: { type: "string" },
          paragrafos: { type: "array", items: { type: "string" } },
          por_que_importa: { type: "string" },
        },
        required: ["id", "titulo", "paragrafos", "por_que_importa"],
        additionalProperties: false,
      },
    },
  },
  required: ["abertura", "itens"],
  additionalProperties: false,
};

const IDIOMAS = { pt: "português", en: "inglês", es: "espanhol", fr: "francês", it: "italiano", de: "alemão" };

function montarPedido(itens, temas, config) {
  const nomeTema = Object.fromEntries(temas.map(t => [t.id, t.nome]));
  const entrada = itens.map(i => ({
    id: i.id,
    editoria: nomeTema[i.tema],
    fonte: i.fonte,
    idioma_original: IDIOMAS[i.idioma] || i.idioma,
    titulo: i.titulo,
    texto: i.trecho,
  }));
  return {
    model: config.MODELO,
    max_tokens: 16000,
    output_config: { effort: "medium", format: { type: "json_schema", schema: ESQUEMA } },
    fallbacks: "default",
    system: INSTRUCOES,
    messages: [{ role: "user", content: `Artigos de hoje:\n\n${JSON.stringify(entrada, null, 2)}` }],
  };
}

function lerResposta(resposta) {
  if (resposta.stop_reason === "refusal") throw new Error("Claude recusou o pedido: " + JSON.stringify(resposta.stop_details));
  if (resposta.stop_reason === "max_tokens") throw new Error("Resposta do Claude foi cortada (max_tokens).");
  const texto = (resposta.content || []).filter(b => b.type === "text").map(b => b.text).join("");
  if (!texto) throw new Error("Resposta do Claude veio sem texto: " + JSON.stringify(resposta).slice(0, 500));
  return JSON.parse(texto);
}

// ---------------------------------------------------------------------------
const memoria = $getWorkflowStaticData("global");
const baixar = url => this.helpers.httpRequest({
  method: "GET", url, timeout: 20000, json: false,
  headers: { "User-Agent": "Mozilla/5.0 (compatible; OsmoNewsletter/1.0; +https://osmo.com.br)", Accept: "application/rss+xml, application/atom+xml, application/xml, text/xml, */*" },
});
const resultado = await coletar(baixar, { temas: TEMAS, config: CONFIG, jaEnviados: memoria.enviados || [] });
if (!resultado.itens.length) throw new Error("Nenhuma notícia nova encontrada. Falhas: " + resultado.falhas.join(" | "));
return [{ json: { ...resultado, pedido: montarPedido(resultado.itens, TEMAS, CONFIG) } }];

